fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Assumptions from the problem:
    // - list is non-empty
    // - 0 < n < list.len()
    debug_assert!(!list.is_empty());
    debug_assert!(n > 0 && n < list.len());

    let len = list.len();
    let mut new_list = Vec::with_capacity(len);

    // Append list[n..len]
    new_list.extend_from_slice(&list[n..]);
    // Append list[0..n]
    new_list.extend_from_slice(&list[..n]);

    new_list
}